{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-3HIis5/src/lexer.js","content":"import { ParseError } from './errors.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*(?:\.[0-9]+(?:_[0-9]+)*)?(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?$/
const HEX = /^[0-9a-fA-F]$/

/** Parses the content of a single line of the document. */
export class Lexer {
  constructor(line) {
    this.line = line
    this.pos = 0
  }

  skipWs() {
    while (this.pos < this.line.length && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
  }

  /** True once nothing but a comment or the end of the line remains. */
  atEnd() {
    if (this.pos >= this.line.length) return true
    const c = this.line[this.pos]
    return c === '#' || c === ';'
  }

  peek() {
    return this.line[this.pos]
  }

  /** A bare word made of the name character set, or a quoted string. */
  parseName() {
    const c = this.line[this.pos]
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    let start = this.pos
    while (this.pos < this.line.length && NAME_CHAR.test(this.line[this.pos])) this.pos++
    if (this.pos === start) throw new ParseError('expected a name')
    return this.line.slice(start, this.pos)
  }

  /** Names joined by `.`, with spaces and tabs allowed around each dot. */
  parseDottedName() {
    const names = []
    this.skipWs()
    names.push(this.parseName())
    for (;;) {
      this.skipWs()
      if (this.line[this.pos] !== '.') break
      this.pos++
      this.skipWs()
      names.push(this.parseName())
    }
    return names
  }

  parseBasicString() {
    this.pos++ // opening quote
    let out = ''
    for (;;) {
      if (this.pos >= this.line.length) throw new ParseError('unterminated string')
      const c = this.line[this.pos]
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.pos >= this.line.length) throw new ParseError('unterminated string')
        const e = this.line[this.pos]
        switch (e) {
          case '"':
            out += '"'
            this.pos++
            break
          case '\\':
            out += '\\'
            this.pos++
            break
          case 'n':
            out += '\n'
            this.pos++
            break
          case 't':
            out += '\t'
            this.pos++
            break
          case 'r':
            out += '\r'
            this.pos++
            break
          case '0':
            out += '\0'
            this.pos++
            break
          case 'u': {
            const digits = this.line.slice(this.pos + 1, this.pos + 5)
            if (digits.length < 4 || !HEX.test(digits[0]) || !HEX.test(digits[1]) || !HEX.test(digits[2]) || !HEX.test(digits[3])) {
              throw new ParseError('invalid escape \\u')
            }
            out += String.fromCharCode(parseInt(digits, 16))
            this.pos += 5
            break
          }
          default:
            throw new ParseError(`invalid escape \\${e}`)
        }
        continue
      }
      out += c
      this.pos++
    }
  }

  parseLiteralString() {
    this.pos++ // opening quote
    let start = this.pos
    while (this.pos < this.line.length && this.line[this.pos] !== "'") this.pos++
    if (this.pos >= this.line.length) throw new ParseError('unterminated string')
    const out = this.line.slice(start, this.pos)
    this.pos++ // closing quote
    return out
  }

  /** A maximal run of characters that are not whitespace or a structural delimiter. */
  readBareToken() {
    const start = this.pos
    while (this.pos < this.line.length) {
      const c = this.line[this.pos]
      if (c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}') break
      this.pos++
    }
    return this.line.slice(start, this.pos)
  }

  /** Parses one value; `path` names it for error messages produced while
   * walking any inline table nested inside. */
  parseValue(path) {
    this.skipWs()
    if (this.atEnd()) throw new ParseError('expected a value')
    const c = this.line[this.pos]
    if (c === '"') return { t: 'string', v: this.parseBasicString() }
    if (c === "'") return { t: 'string', v: this.parseLiteralString() }
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    if (c === ',' || c === ']' || c === '}') throw new ParseError('expected a value')
    const token = this.readBareToken()
    return this.classify(token)
  }

  classify(token) {
    if (token === 'true') return { t: 'boolean', v: true }
    if (token === 'false') return { t: 'boolean', v: false }
    if (INTEGER_RE.test(token)) return { t: 'integer', raw: token.replace(/_/g, '') }
    if (FLOAT_RE.test(token) && /[.eE]/.test(token)) {
      return { t: 'float', v: Number(token.replace(/_/g, '')) }
    }
    throw new ParseError(`invalid value ${token}`)
  }

  parseArray(path) {
    this.pos++ // '['
    const items = []
    this.skipWs()
    if (this.atEnd()) throw new ParseError('unterminated array')
    if (this.line[this.pos] === ']') {
      this.pos++
      return { t: 'array', arr: items }
    }
    for (;;) {
      items.push(this.parseValue(path))
      this.skipWs()
      if (this.atEnd()) throw new ParseError('unterminated array')
      const c = this.line[this.pos]
      if (c === ',') {
        this.pos++
        this.skipWs()
        if (this.atEnd()) throw new ParseError('unterminated array')
        if (this.line[this.pos] === ']') {
          this.pos++
          return { t: 'array', arr: items }
        }
        continue
      }
      if (c === ']') {
        this.pos++
        return { t: 'array', arr: items }
      }
      throw new ParseError('trailing text after a value')
    }
  }

  parseInlineTable(path) {
    this.pos++ // '{'
    const table = { t: 'table', map: new Map(), headerDefined: false }
    this.skipWs()
    if (this.atEnd()) throw new ParseError('unterminated inline table')
    if (this.line[this.pos] === '}') {
      this.pos++
      return table
    }
    for (;;) {
      const names = this.parseDottedName()
      this.skipWs()
      if (this.atEnd() || this.line[this.pos] !== '=') {
        throw new ParseError('expected = in an inline table')
      }
      this.pos++
      const value = this.parseValue([...path, ...names])
      assignInlineKey(table, names, value, path)
      this.skipWs()
      if (this.atEnd()) throw new ParseError('unterminated inline table')
      const c = this.line[this.pos]
      if (c === ',') {
        this.pos++
        this.skipWs()
        if (this.atEnd()) throw new ParseError('unterminated inline table')
        continue
      }
      if (c === '}') {
        this.pos++
        return table
      }
      throw new ParseError('trailing text after a value')
    }
  }
}

function assignInlineKey(table, names, value, prefix) {
  // Imported lazily to avoid a cycle at module load time.
  // eslint-disable-next-line global-require
  const { assignPath } = require_document()
  assignPath(table, names, value, prefix)
}

let cachedDocument
function require_document() {
  if (!cachedDocument) {
    throw new Error('document module not wired up')
  }
  return cachedDocument
}

export function wireDocumentModule(mod) {
  cachedDocument = mod
}
"}

