import { Lexer } from './lexer.js'
import { makeRoot, assignPath, navigateHeader } from './document.js'

/** Parses a whole configuration document into its root table node. */
export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeRoot()
  let current = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    try {
      parseLine(lines[i], root, current, currentPath, (table, path) => {
        current = table
        currentPath = path
      })
    } catch (err) {
      if (err instanceof ParseError) {
        throw new ParseError(err.reason, lineNo)
      }
      throw err
    }
  }

  return root
}

function parseLine(line, root, current, currentPath, setCurrent) {
  const lexer = new Lexer(line)
  lexer.skipWs()
  if (lexer.atEnd()) return // blank or comment-only line

  if (lexer.peek() === '[') {
    parseHeader(lexer, root, setCurrent)
    return
  }

  const names = lexer.parseDottedName()
  lexer.skipWs()
  if (lexer.atEnd() || lexer.peek() !== '=') {
    throw new ParseError('expected key = value')
  }
  lexer.pos++
  const value = lexer.parseValue([...currentPath, ...names])
  lexer.skipWs()
  if (!lexer.atEnd()) throw new ParseError('trailing text after a value')
  assignPath(current, names, value, currentPath)
}

function parseHeader(lexer, root, setCurrent) {
  lexer.pos++ // first '['
  let isArray = false
  if (lexer.line[lexer.pos] === '[') {
    isArray = true
    lexer.pos++
  }

  lexer.skipWs()
  const names = lexer.parseDottedName()
  lexer.skipWs()

  if (lexer.atEnd() || lexer.peek() !== ']') {
    throw new ParseError('unterminated table header')
  }
  lexer.pos++

  if (isArray) {
    if (lexer.line[lexer.pos] !== ']') throw new ParseError('unterminated table header')
    lexer.pos++
  }

  const table = navigateHeader(root, names, isArray)
  setCurrent(table, names)

  lexer.skipWs()
  if (!lexer.atEnd()) throw new ParseError('trailing text after a table header')
}
"}

