{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-3HIis5/src/format.js","content":"/** Compares strings by code point, matching "ascending key order by code point". */
function codePointCompare(a, b) {
  const ai = a[Symbol.iterator]()
  const bi = b[Symbol.iterator]()
  for (;;) {
    const an = ai.next()
    const bn = bi.next()
    if (an.done && bn.done) return 0
    if (an.done) return -1
    if (bn.done) return 1
    const ac = an.value.codePointAt(0)
    const bc = bn.value.codePointAt(0)
    if (ac !== bc) return ac - bc
  }
}

function sortedKeys(table) {
  return [...table.map.keys()].sort(codePointCompare)
}

function typeName(node) {
  switch (node.t) {
    case 'table':
      return 'table'
    case 'atot':
    case 'array':
      return 'array'
    default:
      return node.t
  }
}

/** Renders a value node as canonical JSON, indented by two spaces. */
export function toJSON(root) {
  return render(root, '') + '\n'
}

function render(node, indent) {
  switch (node.t) {
    case 'table':
      return renderEntries(sortedKeys(node).map((k) => [JSON.stringify(k), node.map.get(k)]), indent, '{', '}')
    case 'atot':
      return renderEntries(node.arr.map((item) => [null, item]), indent, '[', ']')
    case 'array':
      return renderEntries(node.arr.map((item) => [null, item]), indent, '[', ']')
    case 'string':
      return JSON.stringify(node.v)
    case 'boolean':
      return String(node.v)
    case 'integer':
      return BigInt(node.raw).toString()
    case 'float':
      return JSON.stringify(node.v)
    default:
      throw new Error(`unknown node kind ${node.t}`)
  }
}

function renderEntries(entries, indent, open, close) {
  if (entries.length === 0) return open + close
  const inner = indent + '  '
  const body = entries
    .map(([key, value]) => `${inner}${key !== null ? key + ': ' : ''}${render(value, inner)}`)
    .join(',\n')
  return `${open}\n${body}\n${indent}${close}`
}

/** Renders one `<path> <type>` line per node below the root, depth first. */
export function toKeys(root) {
  const out = []
  for (const key of sortedKeys(root)) {
    emit(root.map.get(key), key, out)
  }
  return out.map((line) => line + '\n').join('')
}

function emit(node, path, out) {
  out.push(`${path} ${typeName(node)}`)
  if (node.t === 'table') {
    for (const key of sortedKeys(node)) {
      emit(node.map.get(key), `${path}.${key}`, out)
    }
  } else if (node.t === 'atot' || node.t === 'array') {
    node.arr.forEach((item, i) => emit(item, `${path}[${i}]`, out))
  }
}
"}

