/**
 * Walks `names` from `node`, creating a table for each absent step and
 * following the last element when a step already holds an array of tables.
 * `prefix` is the root-relative path to `node`, used to report the full path
 * when a step holds something that cannot be walked through.
 */
export function resolveIntermediate(node, names, prefix, lineNo) {
  for (let i = 0; i < names.length; i++) {
