    let cur = node.entries[name]
    if (cur === undefined) {
      cur = makeTable()
      node.entries[name] = cur
    }
    if (cur.kind === 'table') {
      node = cur
    } else if (cur.kind === 'array-of-tables') {
      node = cur.items[cur.items.length - 1]
    } else {
      const path = joinPath(prefix, names.slice(0, i + 1))
      throw new ParseError(lineNo, `${path} is not a table`)
    }
  }
