  lp.pos++ // consume the leading '['
  let isArray = false
  if (lp.pos < lp.len && lp.line[lp.pos] === '[') {
    isArray = true
    lp.pos++
  }
  lp.skipWs()
  const parts = lp.parseDottedName()
  lp.skipWs()
  if (!(lp.pos < lp.len && lp.line[lp.pos] === ']')) lp.error('unterminated table header')
  lp.pos++
  if (isArray) {
    if (!(lp.pos < lp.len && lp.line[lp.pos] === ']')) lp.error('unterminated table header')
    lp.pos++
  }
  lp.checkTrailing('trailing text after a table header')

  const fullPath = parts.join('.')
  if (isArray) {
    const parentParts = parts.slice(0, -1)
    const lastName = parts[parts.length - 1]
    const parent = resolveIntermediate(root, parentParts, '', lineNo)
    let existing = parent.entries[lastName]
    if (existing === undefined) {
      existing = { kind: 'array-of-tables', items: [] }
      parent.entries[lastName] = existing
    } else if (existing.kind !== 'array-of-tables') {
      throw new ParseError(lineNo, `${fullPath} is not an array of tables`)
    }
    const fresh = makeTable()
    existing.items.push(fresh)
    return { currentTable: fresh, currentPathStr: fullPath }
  }
  const target = resolveIntermediate(root, parts, '', lineNo)
  if (target.headerDefined) throw new ParseError(lineNo, `table ${fullPath} is defined twice`)
  target.headerDefined = true
  return { currentTable: target, currentPathStr: fullPath }
}

