  const parts = lp.parseDottedName()
  lp.skipWs()
  if (!(lp.pos < lp.len && lp.line[lp.pos] === '=')) lp.error('expected key = value')
  lp.pos++
  const childPath = joinPath(currentPathStr, parts)
  const value = lp.parseValue(childPath)
  lp.checkTrailing('trailing text after a value')

  const parentParts = parts.slice(0, -1)
  const lastName = parts[parts.length - 1]
  const parent = resolveIntermediate(currentTable, parentParts, currentPathStr, lineNo)
  if (Object.prototype.hasOwnProperty.call(parent.entries, lastName)) {
    throw new ParseError(lineNo, `key ${childPath} is defined twice`)
  }
  parent.entries[lastName] = value
}

/** Parses a whole configuration document into a root table node. */
export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  let currentTable = root
  let currentPathStr = ''

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const start = firstNonWs(raw)
    if (start === -1) continue
    const c0 = raw[start]
    if (c0 === '#' || c0 === ';') continue

