export function toJSON(root) {
  return render(root, 0)
}

function render(node, level) {
  const pad = '  '.repeat(level)
  const padIn = '  '.repeat(level + 1)
  switch (node.kind) {
    case 'table': {
      const keys = Object.keys(node.entries).sort()
      if (keys.length === 0) return '{}'
      const lines = keys.map((k) => `${padIn}${JSON.stringify(k)}: ${render(node.entries[k], level + 1)}`)
      return `{\n${lines.join(',\n')}\n${pad}}`
    }
    case 'array':
    case 'array-of-tables': {
      const items = node.items
      if (items.length === 0) return '[]'
      const lines = items.map((it) => `${padIn}${render(it, level + 1)}`)
      return `[\n${lines.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

function typeName(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'array':
    case 'array-of-tables':
      return 'array'
    default:
      return node.kind
  }
}

/** Renders `<path> <type>` for every node below the root, depth first. */
export function toKeys(root) {
  const out = []
  walk(root, '', out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}

function walk(node, path, out) {
  if (node.kind === 'table') {
    for (const k of Object.keys(node.entries).sort()) {
      const child = node.entries[k]
      const childPath = path === '' ? k : `${path}.${k}`
      out.push(`${childPath} ${typeName(child)}`)
      walk(child, childPath, out)
    }
  } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
    node.items.forEach((child, i) => {
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeName(child)}`)
      walk(child, childPath, out)
    })
  }
}
