{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { parseInput } from './parse.js'
import { computeChanges } from './diff.js'
import { buildSegments } from './regions.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.includes(mode)) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const input = readFileSync(0, 'utf8')

  let mine, base, theirs
  try {
    ;({ mine, base, theirs } = parseInput(input))
  } catch (error) {
    fail(error.message)
    return
  }

  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const segments = buildSegments(base, mineChanges, theirsChanges)

  const output = []
  let conflict = false

  for (const segment of segments) {
    if (segment.type === 'stable') {
      output.push(...segment.lines)
      continue
    }

    const resolved = segment.resolved
    if (resolved.type === 'conflict') {
      conflict = true
      output.push('<<<<<<< mine')
      output.push(...resolved.mine)
      if (mode === 'merge') {
        output.push('||||||| base')
        output.push(...resolved.base)
      }
      output.push('=======')
      output.push(...resolved.theirs)
      output.push('>>>>>>> theirs')
    } else {
      output.push(...resolved.lines)
    }
  }

  if (mode === 'regions') {
    const lines = []
    for (const segment of segments) {
      if (segment.type === 'stable') {
        lines.push(`stable ${segment.lines.length}`)
        continue
      }
      const resolved = segment.resolved
      if (resolved.type === 'conflict') {
        conflict = true
        lines.push(`conflict mine=${resolved.mine.length} base=${resolved.base.length} theirs=${resolved.theirs.length}`)
      } else {
        lines.push(`${resolved.type} ${resolved.lines.length}`)
      }
    }
    process.stdout.write(lines.map(line => `${line}\n`).join(''))
  } else {
    process.stdout.write(output.map(line => `${line}\n`).join(''))
  }

  process.exit(conflict ? 1 : 0)
}

main()
"}

