    if (s.eof()) s.fail(start, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    if (c === '\n') {
      s.fail(s.pos(), 'newline in string')
    }
    if (c === '\\') {
      value += scanEscape(s)
      continue
    }
    value += c
    s.advance()
  }
  return { kind: 'string', value, line: start.line, column: start.column }
}

function scanRawString(s) {
  const start = s.pos()
  s.advance() // 'r'
  s.advance() // opening quote
  let value = ''
  for (;;) {
    if (s.eof()) s.fail(start, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    value += c
    s.advance()
  }
  return { kind: 'rawstring', value, line: start.line, column: start.column }
}

function scanPunct(s) {
  const start = s.pos()
  const two = s.peek() + (s.peek(1) ?? '')
  if (TWO_CHAR_PUNCT.includes(two)) {
    s.advance()
    s.advance()
    return { kind: 'punct', text: two, line: start.line, column: start.column }
  }
  const one = s.peek()
  if (ONE_CHAR_PUNCT.has(one)) {
    s.advance()
    return { kind: 'punct', text: one, line: start.line, column: start.column }
  }
  s.fail(start, `unexpected character ${one}`)
