/** Scan the whole input into an array of tokens, or throw a `LexError`. */
export function tokenize(text) {
  const s = new Scanner(text)
  const tokens = []
  for (;;) {
    skipTrivia(s)
    if (s.eof()) break
    const c = s.peek()
    if (c === 'r' && s.peek(1) === '"') {
      tokens.push(scanRawString(s))
    } else if (isIdentStart(c)) {
      tokens.push(scanIdent(s))
    } else if (isDigit(c)) {
      tokens.push(scanNumber(s))
    } else if (c === '"') {
      tokens.push(scanString(s))
    } else {
      tokens.push(scanPunct(s))
    }
  }
  return tokens
}
"}

