        }
        const baseText = record.slice(0, spaceIndex)
        const refText = record.slice(spaceIndex + 1)
        const base = parseReference(baseText)
        if (base.scheme === undefined) {
          throw new UsageMistake('the base has no scheme')
        }
        const ref = parseReference(refText)
        const resolved = resolveReference(base, ref)
        results.push(normalize(resolved))
      }
    } catch (err) {
      if (err instanceof TruncatedPercentEncodingError) {
        fail(`line ${lineNumber}: ${err.message}`)
      }
      if (err instanceof UsageMistake) {
        fail(`line ${lineNumber}: ${err.message}`)
      }
      throw err
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

class UsageMistake extends Error {}

main()
