{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-ar5AAB/src/lexer.js","content":"/**
 * Tokenizer for a formula body (the part after the leading `=`). Spaces and
 * tabs are insignificant between tokens. Returns null if any character does
 * not belong to the grammar's token set, signalling a grammar failure to the
 * parser.
 */

const SINGLE = {
  '(': 'LPAREN',
  ')': 'RPAREN',
  ',': 'COMMA',
  ':': 'COLON',
  '+': 'PLUS',
  '-': 'MINUS',
  '*': 'STAR',
  '/': 'SLASH',
  '^': 'CARET',
}

export function tokenize(source) {
  const tokens = []
  let pos = 0
  const len = source.length
  while (pos < len) {
    const c = source[pos]
    if (c === ' ' || c === '\t') {
      pos++
      continue
    }
    if (c >= '0' && c <= '9') {
      const match = /^[0-9]+(\.[0-9]+)?/.exec(source.slice(pos))
      tokens.push({ type: 'NUMBER', text: match[0] })
      pos += match[0].length
      continue
    }
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) {
      const match = /^[A-Za-z]+[0-9]*/.exec(source.slice(pos))
      tokens.push({ type: 'WORD', text: match[0] })
      pos += match[0].length
      continue
    }
    if (c === '<') {
      if (source[pos + 1] === '=') {
        tokens.push({ type: 'LE' })
        pos += 2
      } else if (source[pos + 1] === '>') {
        tokens.push({ type: 'NE' })
        pos += 2
      } else {
        tokens.push({ type: 'LT' })
        pos += 1
      }
      continue
    }
    if (c === '>') {
      if (source[pos + 1] === '=') {
        tokens.push({ type: 'GE' })
        pos += 2
      } else {
        tokens.push({ type: 'GT' })
        pos += 1
      }
      continue
    }
    if (c === '=') {
      tokens.push({ type: 'EQ' })
      pos += 1
      continue
    }
    if (Object.prototype.hasOwnProperty.call(SINGLE, c)) {
      tokens.push({ type: SINGLE[c] })
      pos += 1
      continue
    }
    return null
  }
  return tokens
}
"}

