        return { type: 'Bool', value: true }
      }
      if (upper === 'FALSE') {
        this.next()
        return { type: 'Bool', value: false }
      }

      if (next1 && next1.type === 'LPAREN') {
        this.next() // word
        this.next() // lparen
        const args = []
        if (!this.peek() || this.peek().type !== 'RPAREN') {
          const first = this.parseComparison()
          if (first === null) return null
          args.push(first)
          while (this.peek() && this.peek().type === 'COMMA') {
            this.next()
            const arg = this.parseComparison()
            if (arg === null) return null
            args.push(arg)
          }
        }
        if (!this.peek() || this.peek().type !== 'RPAREN') return null
        this.next()
        if (!Object.prototype.hasOwnProperty.call(CALL_ARITY, upper)) {
          return { type: 'Call', name: upper, args, known: false }
        }
        const arity = CALL_ARITY[upper]
        const arityOk = arity === 'many' ? args.length >= 1 : args.length === arity
        return { type: 'Call', name: upper, args, known: true, arityOk }
      }

      this.next()
      return { type: 'Address', ...decomposeWord(token.text) }
    }

    return null
  }
}

