 * Classifies a literal cell's raw content (anything not starting with `=`)
 * into the number/error/text it stands for.
 */
import { numberValue, textValue, errorValue, ERROR_TOKENS } from './values.js'

const LITERAL_NUMBER = /^-?[0-9]+(\.[0-9]+)?$/

export function resolveLiteral(content) {
  if (content === '') return numberValue(0)
  if (LITERAL_NUMBER.test(content)) return numberValue(Number(content))
  if (ERROR_TOKENS.includes(content)) return errorValue(content)
  return textValue(content)
}
"}

