{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-ar5AAB/src/sheet.js","content":"/**
 * Parses the sheet source text into a map of declared cells, keyed by their
 * canonical (upper-cased) address. Each cell records its content's kind:
 * a resolved literal value, or a parsed formula AST (null if the formula's
 * grammar does not accept it).
 */
import { isStrictAddress } from './address.js'
import { resolveLiteral } from './literal.js'
import { parseFormula } from './parser.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const line = lines[i]
    const stripped = line.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    const wsMatch = /[ \t]/.exec(stripped)
    let addressToken
    let content
    if (wsMatch === null) {
      addressToken = stripped
      content = ''
    } else {
      addressToken = stripped.slice(0, wsMatch.index)
      const afterAddress = stripped.slice(wsMatch.index)
      const runMatch = /^[ \t]+/.exec(afterAddress)
      content = afterAddress.slice(runMatch[0].length)
    }

    if (!isStrictAddress(addressToken)) {
      throw new SheetError(lineNumber, `invalid cell address ${addressToken}`)
    }
    const address = addressToken.toUpperCase()
    if (cells.has(address)) {
      throw new SheetError(lineNumber, `cell ${address} is declared twice`)
    }

    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      cells.set(address, { kind: 'formula', ast })
    } else {
      cells.set(address, { kind: 'literal', value: resolveLiteral(content) })
    }
  }

  return cells
}
"}

