/**
 * Turns an alignment between the base and one side into the list of changes
 * that side made: each change is a run of base lines (given as a
 * half-open `[start, end)` range) replaced by a run of that side's lines. An
 * insertion has `start === end`; a deletion has empty `lines`.
 */
function computeChanges(base, side) {
  const matches = alignLines(base, side)
  const changes = []
  let prevI = -1
  let prevJ = -1
  const advance = (i, j) => {
    if (i > prevI + 1 || j > prevJ + 1) {
      changes.push({ start: prevI + 1, end: i, lines: side.slice(prevJ + 1, j) })
    }
    prevI = i
    prevJ = j
  }
  for (const [i, j] of matches) advance(i, j)
  advance(base.length, side.length)
  return changes
}

function compareChanges(a, b) {
  if (a.start !== b.start) return a.start - b.start
  return a.source === 'mine' ? -1 : 1
}

/**
 * Groups a list of changes (sorted by base start, mine before theirs on a
 * tie) into regions: each region starts at the first remaining change's base
 * start, and keeps absorbing following changes while they start at or before
 * the region's current base end, extending that end to cover them.
 */
function groupRegions(changes) {
  const regions = []
  let idx = 0
  while (idx < changes.length) {
    let start = changes[idx].start
    let end = changes[idx].end
    const group = [changes[idx]]
    idx++
    while (idx < changes.length && changes[idx].start <= end) {
      end = Math.max(end, changes[idx].end)
      group.push(changes[idx])
      idx++
    }
    regions.push({ start, end, changes: group })
  }
  return regions
}

/**
 * Reconstructs one side's replacement for a region: the base lines the
 * region covers that none of that side's changes touch stay as they are, and
 * each change's own lines are spliced in at its place.
 */
function buildSideLines(base, changes, regionStart, regionEnd) {
  const lines = []
  let cursor = regionStart
  for (const change of changes) {
    if (change.start > cursor) lines.push(...base.slice(cursor, change.start))
    lines.push(...change.lines)
    cursor = change.end
  }
  if (cursor < regionEnd) lines.push(...base.slice(cursor, regionEnd))
  return lines
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Computes the three-way merge of `mine` and `theirs` against their common
 * `base`, as a list of regions in base order. Each region is one of:
 *   - `{ type: 'stable', lines }` — base lines neither side changed
 *   - `{ type: 'mine' | 'theirs', lines }` — lines the merge resolved to
 *   - `{ type: 'both', lines }` — both sides made the same change
 *   - `{ type: 'conflict', mine, base, theirs }` — lines that could not be
 *     resolved automatically
 */
export function diff3Merge(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(change => ({ ...change, source: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(change => ({ ...change, source: 'theirs' }))
  const combined = [...mineChanges, ...theirsChanges].sort(compareChanges)
  const changeRegions = groupRegions(combined)

  const regions = []
  let cursor = 0
  for (const region of changeRegions) {
    if (region.start > cursor) regions.push({ type: 'stable', lines: base.slice(cursor, region.start) })

    const mineTouches = region.changes.filter(change => change.source === 'mine')
    const theirsTouches = region.changes.filter(change => change.source === 'theirs')
    const mineLines = mineTouches.length ? buildSideLines(base, mineTouches, region.start, region.end) : null
    const theirsLines = theirsTouches.length ? buildSideLines(base, theirsTouches, region.start, region.end) : null

    if (mineLines && !theirsLines) {
      regions.push({ type: 'mine', lines: mineLines })
    } else if (theirsLines && !mineLines) {
      regions.push({ type: 'theirs', lines: theirsLines })
    } else {
      const baseLines = base.slice(region.start, region.end)
      if (arraysEqual(mineLines, theirsLines)) regions.push({ type: 'both', lines: mineLines })
      else if (arraysEqual(mineLines, baseLines)) regions.push({ type: 'theirs', lines: theirsLines })
      else if (arraysEqual(theirsLines, baseLines)) regions.push({ type: 'mine', lines: mineLines })
      else regions.push({ type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    cursor = region.end
  }
  if (cursor < base.length) regions.push({ type: 'stable', lines: base.slice(cursor, base.length) })

