{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-goQwRp/src/policies.js","content":"/**
 * The two policy kinds a route can apply to a key: a token bucket and a
 * sliding window. Each keeps one independent state per key it has seen.
 */

/**
 * A token bucket. Tokens are tracked as `numerator / per` so that partial
 * refill periods stay exact: `numerator` holds `tokens * per`, which is
 * always a whole number since `refill` and `per` are integers.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.max = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    const state = this.states.get(key)
    if (state === undefined) {
      this.states.set(key, { numerator: this.max, lastTick: tick })
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      let numerator = state.numerator + this.refill * delta
      if (numerator > this.max) numerator = this.max
      state.numerator = numerator
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.states.get(key).numerator >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.numerator -= this.per
  }
}

/** A sliding window. Remembers the ticks of the requests it recorded. */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let queue = this.states.get(key)
    if (queue === undefined) {
      queue = []
      this.states.set(key, queue)
    }
    const threshold = tick - this.span
    while (queue.length > 0 && queue[0] <= threshold) queue.shift()
  }

  allows(key) {
    const queue = this.states.get(key)
    return BigInt(queue.length) < this.limit
  }

  record(key, tick) {
    this.states.get(key).push(tick)
  }
}
"}

