{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-goQwRp/src/simulate.js","content":"/**
 * Replays a parsed limiter file's event log against its policies, producing
 * either a per-event verdict trace or a per-key allow/deny summary.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

function buildInstances(policies) {
  const instances = new Map()
  for (const [name, spec] of policies) {
    instances.set(
      name,
      spec.type === 'bucket'
        ? new TokenBucket(spec.capacity, spec.refill, spec.per)
        : new SlidingWindow(spec.limit, spec.span),
    )
  }
  return instances
}

/** Finds the route whose prefix matches the key and is longest, if any. */
function findRoute(routeList, key) {
  let best = null
  for (const route of routeList) {
    if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

/**
 * Runs the event log against the declared policies and routes, returning
 * one verdict per event plus per-key and total allow/deny tallies.
 */
export function simulate(model) {
  const instances = buildInstances(model.policies)
  const verdicts = []
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  for (const event of model.events) {
    const route = findRoute(model.routeList, event.key)
    let allowed = true
    let denyPolicy = null

    if (route !== null) {
      for (const name of route.policies) instances.get(name).advance(event.key, event.tick)
      for (const name of route.policies) {
        if (!instances.get(name).allows(event.key)) {
          allowed = false
          denyPolicy = name
          break
        }
      }
      if (allowed) {
        for (const name of route.policies) instances.get(name).record(event.key, event.tick)
      }
    }

    verdicts.push({ tick: event.tick, key: event.key, allowed, denyPolicy })

    let tally = perKey.get(event.key)
    if (tally === undefined) {
      tally = { allowed: 0, denied: 0 }
      perKey.set(event.key, tally)
    }
    if (allowed) {
      tally.allowed += 1
      totalAllowed += 1
    } else {
      tally.denied += 1
      totalDenied += 1
    }
  }

  return { verdicts, perKey, totalAllowed, totalDenied }
}
"}

