{"file_path":"src/sheet.js","content":"/**
 * Parse a sheet from raw standard input text into a map of address to
 * declared cell content, per the line format in the task specification.
 */

import { isValidAddress } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    const addrMatch = /^[^ \t]+/.exec(line)
    const addrRaw = addrMatch[0]
    const rest = line.slice(addrRaw.length).replace(/^[ \t]+/, '')
    const addr = addrRaw.toUpperCase()

    if (!isValidAddress(addr)) {
      throw new SheetError(lineNo, `invalid cell address ${addr}`)
    }
    if (cells.has(addr)) {
      throw new SheetError(lineNo, `cell ${addr} is declared twice`)
    }
    cells.set(addr, rest)
  }
  return cells
}
"}

{"file_path":"src/tokenizer.js","content":"/**
 * Tokenizer for formula bodies (the text after a leading `=`).
 */

export class LexError extends Error {}

// Order matters: longer operator spellings must be tried before their
// single-character prefixes.
const SPECS = [
  { type: 'WS', re: /^[ \t]+/ },
  { type: 'NUMBER', re: /^\d+(\.\d+)?/ },
  { type: 'NAME', re: /^[A-Za-z]+\d*/ },
  { type: 'LE', re: /^<=/ },
  { type: 'GE', re: /^>=/ },
  { type: 'NE', re: /^<>/ },
  { type: 'LT', re: /^</ },
  { type: 'GT', re: /^>/ },
  { type: 'EQ', re: /^=/ },
  { type: 'PLUS', re: /^\+/ },
  { type: 'MINUS', re: /^-/ },
  { type: 'STAR', re: /^\*/ },
  { type: 'SLASH', re: /^\// },
  { type: 'CARET', re: /^\^/ },
  { type: 'LPAREN', re: /^\(/ },
  { type: 'RPAREN', re: /^\)/ },
  { type: 'COMMA', re: /^,/ },
  { type: 'COLON', re: /^:/ },
]

export function tokenize(text) {
  const tokens = []
  let pos = 0
  while (pos < text.length) {
    const chunk = text.slice(pos)
    let matched = null
    for (const spec of SPECS) {
      const m = spec.re.exec(chunk)
      if (m) {
        matched = { type: spec.type, text: m[0] }
        break
      }
    }
    if (!matched) throw new LexError(`unexpected character at ${pos}`)
    pos += matched.text.length
    if (matched.type !== 'WS') tokens.push(matched)
  }
  return tokens
}
"}

{"file_path":"src/values.js","content":"/**
 * Value representation and the shared arithmetic/comparison semantics used
 * by the formula evaluator: a value is a number, text, a boolean, or an
 * error token.
 */

export function numberValue(v) {
  return { kind: 'number', value: v }
}
export function textValue(v) {
  return { kind: 'text', value: v }
}
export function boolValue(v) {
  return { kind: 'bool', value: v }
}
export function errorValue(token) {
  return { kind: 'error', value: token }
}

export const ERR_DIV0 = errorValue('#DIV/0!')
export const ERR_REF = errorValue('#REF!')
export const ERR_VALUE = errorValue('#VALUE!')
export const ERR_CYCLE = errorValue('#CYCLE!')
export const ERR_NAME = errorValue('#NAME?')
export const ERR_ERR = errorValue('#ERR!')

export const ERROR_TOKENS = new Set([
  '#DIV/0!',
  '#REF!',
  '#VALUE!',
  '#CYCLE!',
  '#NAME?',
  '#ERR!',
])

/** Read a value as a number for arithmetic: booleans convert, text errors. */
export function toNumber(v) {
  if (v.kind === 'error') return v
  if (v.kind === 'number') return v
  if (v.kind === 'bool') return numberValue(v.value ? 1 : 0)
  return ERR_VALUE
}

/** Read a value as a boolean condition: booleans and numbers convert. */
export function toBoolean(v) {
  if (v.kind === 'error') return v
  if (v.kind === 'bool') return v
  if (v.kind === 'number') return boolValue(v.value !== 0)
  return ERR_VALUE
}

function finiteOrDiv0(n) {
  return Number.isFinite(n) ? numberValue(n) : ERR_DIV0
}

/** Apply an arithmetic operator to two already-numeric operands. */
export function arithmetic(op, a, b) {
  switch (op) {
    case '+':
      return finiteOrDiv0(a + b)
    case '-':
      return finiteOrDiv0(a - b)
    case '*':
      return finiteOrDiv0(a * b)
    case '/':
      if (b === 0) return ERR_DIV0
      return finiteOrDiv0(a / b)
    case '^':
      return finiteOrDiv0(Math.pow(a, b))
    default:
      throw new Error(`unknown arithmetic operator ${op}`)
  }
}

const KIND_RANK = { number: 0, text: 1, bool: 2 }

/** Compare two non-error values per the cross-kind ordering rules. */
export function compareValues(op, l, r) {
  let cmp
  if (l.kind === r.kind) {
    if (l.kind === 'number' || l.kind === 'text') {
      cmp = l.value < r.value ? -1 : l.value > r.value ? 1 : 0
    } else {
      cmp = l.value === r.value ? 0 : l.value ? 1 : -1
    }
  } else {
    cmp = KIND_RANK[l.kind] - KIND_RANK[r.kind]
  }
  let result
  switch (op) {
    case '=':
      result = cmp === 0
      break
    case '<>':
      result = cmp !== 0
      break
    case '<':
      result = cmp < 0
      break
    case '<=':
      result = cmp <= 0
      break
    case '>':
      result = cmp > 0
      break
    case '>=':
      result = cmp >= 0
      break
    default:
      throw new Error(`unknown comparison operator ${op}`)
  }
  return boolValue(result)
}

/** Round to ten significant digits and print as JavaScript would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  let rounded = Number(n.toPrecision(10))
  if (Object.is(rounded, -0)) rounded = 0
  return String(rounded)
}

export function formatValue(v) {
  switch (v.kind) {
    case 'number':
      return formatNumber(v.value)
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'error':
      return v.value
    case 'text':
      return v.value
    default:
      throw new Error(`unknown value kind ${v.kind}`)
  }
}
"}

