{"file_path":"src/evaluator.js","content":"/**
 * Evaluates cell contents: literals directly, formulas by walking the AST
 * produced by the parser. Handles memoization, cycle detection, and the
 * built-in functions.
 */

import { parseFormula, ParseError } from './parser.js'
import { expandRange, isValidAddress } from './address.js'
import {
  numberValue,
  textValue,
  boolValue,
  errorValue,
  ERR_DIV0,
  ERR_REF,
  ERR_VALUE,
  ERR_CYCLE,
  ERR_NAME,
  ERR_ERR,
  ERROR_TOKENS,
  toNumber,
  toBoolean,
  arithmetic,
  compareValues,
} from './values.js'

const NUMERIC_LITERAL_RE = /^-?\d+(\.\d+)?$/
const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const VARIADIC_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

function parseLiteral(content) {
  if (content === '') return numberValue(0)
  if (ERROR_TOKENS.has(content)) return errorValue(content)
  if (NUMERIC_LITERAL_RE.test(content)) return numberValue(parseFloat(content))
  return textValue(content)
}

/** Value {kind:'error'} for a text operand, else null. */
function arithProblem(v) {
  if (v.kind === 'error') return v
  if (v.kind === 'text') return ERR_VALUE
  return null
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells // Map address -> declared content string
    this.parsed = new Map() // address -> ast | null (null means grammar failure)
    this.values = new Map() // address -> Value
    this.visiting = new Set()
  }

  getAst(addr) {
    if (this.parsed.has(addr)) return this.parsed.get(addr)
    const content = this.cells.get(addr) ?? ''
    let ast = null
    if (content.startsWith('=')) {
      try {
        ast = parseFormula(content.slice(1))
      } catch (e) {
        if (!(e instanceof ParseError)) throw e
      }
    }
    this.parsed.set(addr, ast)
    return ast
  }

  evaluateCell(addr) {
    if (this.values.has(addr)) return this.values.get(addr)
    if (this.visiting.has(addr)) {
      this.values.set(addr, ERR_CYCLE)
      return ERR_CYCLE
    }
    this.visiting.add(addr)
    const content = this.cells.get(addr) ?? ''
    let result
    if (content.startsWith('=')) {
      const ast = this.getAst(addr)
      result = ast === null ? ERR_ERR : evaluate(ast, this)
    } else {
      result = parseLiteral(content)
    }
    this.visiting.delete(addr)
    this.values.set(addr, result)
    return result
  }
}

function evaluate(node, ctx) {
  switch (node.type) {
    case 'num':
      return numberValue(node.value)
    case 'bool':
      return boolValue(node.value)
    case 'ref':
      return isValidAddress(node.address) ? ctx.evaluateCell(node.address) : ERR_REF
    case 'range':
      // The grammar only ever places a range node directly as a function
      // argument, so this position is never actually reached.
      return ERR_ERR
    case 'unary':
      return evaluateUnary(node, ctx)
    case 'binop':
      return evaluateBinop(node, ctx)
    case 'call':
      return evaluateCall(node, ctx)
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

function evaluateUnary(node, ctx) {
  const v = evaluate(node.expr, ctx)
  const n = toNumber(v)
  if (n.kind === 'error') return n
  const r = node.op === '-' ? -n.value : n.value
  return Number.isFinite(r) ? numberValue(r) : ERR_DIV0
}

function evaluateBinop(node, ctx) {
  const l = evaluate(node.left, ctx)
  const r = evaluate(node.right, ctx)
  if (COMPARISON_OPS.has(node.op)) {
    if (l.kind === 'error') return l
    if (r.kind === 'error') return r
    return compareValues(node.op, l, r)
  }
  const lProblem = arithProblem(l)
  if (lProblem) return lProblem
  const rProblem = arithProblem(r)
  if (rProblem) return rProblem
  return arithmetic(node.op, toNumber(l).value, toNumber(r).value)
}

/** Expand a single function argument (range or expression) to one value. */
function argToScalar(node, ctx) {
  if (node.type === 'range') {
    const cells = expandRange(node.from, node.to)
    if (cells === null) return ERR_REF
    for (const a of cells) {
      const v = ctx.evaluateCell(a)
      if (v.kind === 'error') return v
    }
    return ctx.evaluateCell(cells[0])
  }
  return evaluate(node, ctx)
}

/** Expand every argument (ranges included) into a flat left-to-right list. */
function flattenArgs(argNodes, ctx) {
  const items = []
  for (const node of argNodes) {
    if (node.type === 'range') {
      const cells = expandRange(node.from, node.to)
      if (cells === null) {
        items.push(ERR_REF)
      } else {
        for (const a of cells) items.push(ctx.evaluateCell(a))
      }
    } else {
      items.push(evaluate(node, ctx))
    }
  }
  return items
}

function applyVariadic(name, items) {
  if (name === 'COUNT') {
    for (const v of items) {
      if (v.kind === 'error') return v
    }
    return numberValue(items.filter((v) => v.kind === 'number').length)
  }

  const nums = []
  for (const v of items) {
    if (v.kind === 'error') return v
    const n = toNumber(v)
    if (n.kind === 'error') return n
    nums.push(n.value)
  }

  let r
  switch (name) {
    case 'SUM':
      r = nums.reduce((a, b) => a + b, 0)
      break
    case 'MIN':
      r = Math.min(...nums)
      break
    case 'MAX':
      r = Math.max(...nums)
      break
    case 'AVG':
      r = nums.reduce((a, b) => a + b, 0) / nums.length
      break
    default:
      throw new Error(`unknown variadic function ${name}`)
  }
  return Number.isFinite(r) ? numberValue(r) : ERR_DIV0
}

function evaluateCall(node, ctx) {
  const { name, args } = node

  if (name === 'IF') {
    if (args.length !== 3) return ERR_ERR
    const condBool = toBoolean(argToScalar(args[0], ctx))
    if (condBool.kind === 'error') return condBool
    return argToScalar(condBool.value ? args[1] : args[2], ctx)
  }

  if (name === 'ABS') {
    if (args.length !== 1) return ERR_ERR
    const n = toNumber(argToScalar(args[0], ctx))
    if (n.kind === 'error') return n
    const r = Math.abs(n.value)
    return Number.isFinite(r) ? numberValue(r) : ERR_DIV0
  }

  if (VARIADIC_FUNCTIONS.has(name)) {
    if (args.length < 1) return ERR_ERR
    return applyVariadic(name, flattenArgs(args, ctx))
  }

  return ERR_NAME
}
"}

